const encode = (text) => Buffer.from(text, 'utf8').toString('base64url');
const messages = [
  {
    id: 'synthetic-interview-001',
    threadId: 'synthetic-thread-001',
    payload: {
      mimeType: 'text/plain',
      headers: [
        { name: 'From', value: 'Example Hiring Team <hiring@example.test>' },
        { name: 'Subject', value: 'Synthetic interview invitation' },
      ],
      body: { data: encode('We would like to schedule an interview.') },
    },
  },
  {
    id: 'synthetic-confirmation-002',
    threadId: 'synthetic-thread-002',
    payload: {
      mimeType: 'text/plain',
      headers: [
        { name: 'From', value: 'Example Careers <careers@example.test>' },
        { name: 'Subject', value: 'Synthetic application confirmation' },
      ],
      body: { data: encode("We've received your application.") },
    },
  },
  {
    id: 'synthetic-alert-003',
    threadId: 'synthetic-thread-003',
    payload: {
      mimeType: 'text/plain',
      headers: [
        { name: 'From', value: 'Example Jobs <jobs@example.test>' },
        { name: 'Subject', value: 'Synthetic job alert' },
      ],
      body: { data: encode('New jobs matching your preferences.') },
    },
  },
];
return [{ json: { messages } }];

const { processSyntheticBatch } = require('mailflow-pipeline');
const input = $input.first()?.json;
return [{ json: processSyntheticBatch(input?.messages) }];
